# domain generalized architecture search 
bash script/command.sh ft-s0-vit-pacs    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task PACS --source photo --target art_painting cartoon sketch --num_classes 7 --alpha 0.0 --wd 1e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-pacs --finetune_ckpt supernet-small"
bash script/command.sh ft-s0-vit-vlcs    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task VLCS --source CALTECH  --target LABELME PASCAL SUN --num_classes 5 --alpha 0.0 --wd 5e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-vlcs --finetune_ckpt supernet-small"
bash script/command.sh ft-s0-vit-oh    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task OfficeHome --source RealWorld --target Art Clipart Product --num_classes 10 --alpha 0.0 --wd 1e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-oh --finetune_ckpt supernet-small"
bash script/command.sh ft-s0-vit-dn    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task DomainNet --source real --target infograph painting quickdraw clipart sketch --num_classes 10 --alpha 0.0 --wd 1e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-dn --finetune_ckpt supernet-small"

bash script/command.sh ft-s0-vit-pacs-aug    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task PACS --source photo --target art_painting cartoon sketch --num_classes 7 --alpha 0.0 --wd 1e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-pacs-aug --finetune_ckpt supernet-small"
bash script/command.sh ft-s0-vit-vlcs-aug    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task VLCS --source CALTECH  --target LABELME PASCAL SUN --num_classes 5 --alpha 0.0 --wd 5e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-vlcs-aug --finetune_ckpt supernet-small"
bash script/command.sh ft-s0-vit-oh-aug    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task OfficeHome --source RealWorld --target Art Clipart Product --num_classes 10 --alpha 0.0 --wd 1e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-oh-aug --finetune_ckpt supernet-small"
bash script/command.sh ft-s0-vit-dn-aug    "torchrun --standalone --nnodes=1 --nproc_per_node=2 gpt_search_finetune_former.py --split 0     --model vit --task DomainNet --source real --target infograph painting quickdraw clipart sketch --num_classes 10 --alpha 0.0 --wd 1e-4 --epochs 50  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/supernet/supernet-S.yaml --checkpoint ft-s0-vit-dn-aug --finetune_ckpt supernet-small"


# retrain after domain generalized architecture search
bash script/command.sh rt-s0-vit-pacs    "torchrun --standalone --nnodes=1 --nproc_per_node=2 train_cls_superformer.py --split 0     --model vit --task PACS --source photo --target art_painting cartoon sketch --num_classes 7 --alpha 0.0 --wd 1e-4 --epochs 200  --lr 5e-3 --bs 32 --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/subnet/PACS/AutoFormer-S.yaml --checkpoint rt-s0-vit-pacs --finetune_ckpt supernet-small"
bash script/command.sh rt-s0-vit-vlcs    "torchrun --standalone --nnodes=1 --nproc_per_node=2 train_cls_superformer.py --split 0     --model vit --task VLCS --source CALTECH --target LABELME PASCAL SUN --num_classes 5 --alpha 0.0 --wd 5e-4 --epochs 200  --lr 5e-3 --bs 32 --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/subnet/VLCS/AutoFormer-S.yaml --checkpoint rt-s0-vit-vlcs --finetune_ckpt supernet-small"
bash script/command.sh rt-s0-vit-oh    "torchrun --standalone --nnodes=1 --nproc_per_node=2 train_cls_superformer.py --split 0     --model vit --task OfficeHome --source RealWorld --target Art Clipart Product --num_classes 10 --alpha 0.0 --wd 1e-4 --epochs 200  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/subnet/OfficeHome/AutoFormer-S.yaml --checkpoint rt-s0-vit-oh --finetune_ckpt supernet-small"
bash script/command.sh rt-s0-vit-dn    "torchrun --standalone --nnodes=1 --nproc_per_node=2 train_cls_superformer.py --split 0     --model vit --task DomainNet --source real --target infograph painting quickdraw clipart sketch --num_classes 10 --alpha 0.0 --wd 1e-4 --epochs 200  --lr 5e-3 --bs 32  --img_size 224 --arch vit_entangle_patch16_224  --cfg experiments/subnet/DomainNet/AutoFormer-S.yaml --checkpoint rt-s0-vit-dn --finetune_ckpt supernet-small"


